const STORAGE_KEY='supersonic-mail-v1';
let state;let storageWorks=true;
try{state=JSON.parse(localStorage.getItem(STORAGE_KEY));}catch{storageWorks=false;}
if(!state || !Array.isArray(state.messages))state={messages:seeds,drafts:[],labels:['Work','Personal','Reading list']};
state.drafts ||= []; state.labels ||= ['Work','Personal','Reading list'];
let folder='inbox',split='important',labelFilter='',unreadOnly=false,selected=1,opened=null,undoStack=[],paletteMode='commands',paletteItems=[],paletteIndex=0,labelTarget=null,editingDraftId=null,toastTimer;
const now=new Date();let calendarMonth=new Date(now.getFullYear(),now.getMonth(),1),calendarDay=new Date(now.getFullYear(),now.getMonth(),now.getDate());
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageWorks=true;}catch{storageWorks=false;$('.local-status').textContent='Demo inbox · Session only';}if(!storageWorks)$('.mail-footer>span').textContent='Session only · Storage unavailable';}
function saveUndo(){undoStack.push(JSON.stringify(state));if(undoStack.length>20)undoStack.shift();}
function undo(){if(!undoStack.length)return toast('Nothing to undo.');state=JSON.parse(undoStack.pop());save();render();if(opened&&!state.messages.some(m=>m.id===opened))back();toast('Last action undone.');}
function toast(message,canUndo=false){const t=$('#toast');t.innerHTML=`<span>${esc(message)}</span>${canUndo?'<button id="toast-undo">Undo <kbd>Z</kbd></button>':''}`;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4500);if(canUndo)$('#toast-undo').onclick=undo;}
function wakeSnoozed(){let changed=false;state.messages.forEach(m=>{if(m.folder==='snoozed'&&m.snoozeUntil<=Date.now()){m.folder='inbox';delete m.snoozeUntil;changed=true;}});if(changed){save();render();}}
function visibleMessages(){if(folder==='drafts')return state.drafts.map(d=>({...d,name:d.to||'New draft',initials:'AJ',color:'#e9e3f4',ink:'#9c8ab0',preview:d.body,time:'Draft',unread:false}));return state.messages.filter(m=>{if(labelFilter&&m.label!==labelFilter)return false; if(folder==='starred'){if(!m.starred)return false;}else if(m.folder!==folder)return false;if(folder==='inbox'&&!labelFilter&&m.split!==split)return false;return !unreadOnly||m.unread;});}
function render(){renderLabels();const list=visibleMessages();if(!list.some(m=>m.id===selected))selected=list[0]?.id??null;
const inbox=state.messages.filter(m=>m.folder==='inbox');$('#inbox-count').textContent=inbox.length||'';$('#starred-count').textContent=state.messages.filter(m=>m.starred).length||'';$('#snoozed-count').textContent=state.messages.filter(m=>m.folder==='snoozed').length||'';$('#drafts-count').textContent=state.drafts.length||'';
$('#important-count').textContent=inbox.filter(m=>m.split==='important').length;$('#other-count').textContent=inbox.filter(m=>m.split==='other').length;
$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.folder===folder&&!labelFilter));$$('.split-tab').forEach(b=>{b.classList.toggle('active',b.dataset.split===split);b.setAttribute('aria-selected',b.dataset.split===split);});
const title=labelFilter||({inbox:'Inbox',starred:'Starred',snoozed:'Snoozed',sent:'Sent',drafts:'Drafts',done:'Done'}[folder]);$('#folder-title').innerHTML=`${esc(title)}<span class="heading-dot">.</span>`;$('#breadcrumb').textContent=title;document.title=`${title} · Supersonic`;$('#folder-description').textContent=({inbox:'A clear mind starts with a clear inbox.',starred:'The conversations you want to come back to.',snoozed:'Out of sight, until the time is right.',sent:'Good thoughts, sent on their way. Demo messages only.',drafts:'A few thoughts still taking shape.',done:'A little less on your mind.'}[folder]);
$('.split-tabs').style.visibility=folder==='inbox'&&!labelFilter?'visible':'hidden';$('#conversation-count').textContent=`${list.length} conversation${list.length===1?'':'s'}`;$('#unread-label').textContent=list.filter(m=>m.unread).length?`${list.filter(m=>m.unread).length} unread`:'';$('#list-day').textContent=unreadOnly?'UNREAD':folder==='snoozed'?'COMING BACK LATER':folder==='drafts'?'WORK IN PROGRESS':'TODAY';$('#filter-unread').classList.toggle('unread-filter-on',unreadOnly);
$('#mail-list').innerHTML=list.length?list.map(m=>`<article class="mail-row ${m.unread?'unread':''} ${selected===m.id?'selected':''}" data-id="${m.id}" tabindex="0" aria-label="${esc(m.name+': '+m.subject)}"><div class="sender-avatar" style="background:${m.color};color:${m.ink}">${esc(m.initials)}</div><div class="mail-content"><div class="mail-top"><span class="sender-name">${esc(m.name)}</span>${m.thread?`<span class="thread-count">${m.thread}</span>`:''}${m.unread?'<i class="unread-dot"></i>':''}${m.label?`<span class="mail-label">${esc(m.label)}</span>`:''}<time class="mail-time">${m.folder==='snoozed'?esc(new Date(m.snoozeUntil).toLocaleDateString(undefined,{month:'short',day:'numeric'})):esc(m.time)}</time></div><div class="mail-bottom"><span class="mail-subject">${esc(m.subject||'(No subject)')}</span><span class="preview-dash">—</span><span class="mail-preview">${esc(m.preview)}</span></div></div>${folder!=='drafts'?`<button class="row-star ${m.starred?'is-starred':''}" data-star="${m.id}" aria-label="${m.starred?'Unstar':'Star'} conversation" title="${m.starred?'Unstar':'Star'}">${icon('star')}</button>`:''}</article>`).join(''):`<div class="empty-state">${icon(folder==='inbox'?'checkCircle':folder==='snoozed'?'clock':'inbox')}<h2>${unreadOnly?'All caught up.':folder==='inbox'?'Hello, breathing room.':folder==='drafts'?'A blank page awaits.':folder==='done'?'Good things take one step.':folder==='sent'?'Your next good conversation.':folder==='snoozed'?'Nothing waiting in the wings.':'A little space for what matters.'}</h2><p>${unreadOnly?'No unread conversations in this view.':folder==='inbox'?'You’ve made room for the rest of your day.':folder==='drafts'?'Hit C to start a new message.':folder==='done'?'Hit E on a conversation to mark it done.':folder==='sent'?'Messages you send in this demo will appear here.':folder==='snoozed'?'Snooze a conversation and it will return when you’re ready.':'Star a conversation to find it here.'}</p></div>`;
$('#inbox-end').hidden=!list.length;$('.focus-card').hidden=!list.length;
$$('.mail-row').forEach(row=>{row.onclick=e=>{if(e.target.closest('[data-star]'))return;selected=Number(row.dataset.id);if(folder==='drafts')openDraft(selected);else openMessage(selected);};row.onkeydown=e=>{if(e.key==='Enter'&&e.target===row){e.preventDefault();e.stopPropagation();row.click();}};});$$('[data-star]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleStar(Number(b.dataset.star));});hydrateIcons();}
function renderLabels(){$('#labels').innerHTML=state.labels.map((l,i)=>`<button class="label-item ${labelFilter===l?'active':''}" data-label="${esc(l)}"><i class="label-dot ${['lavender','peach','mint'][i%3]}"></i>${esc(l)}<span>${state.messages.filter(m=>m.label===l&&m.folder==='inbox').length||''}</span></button>`).join('');$$('[data-label]').forEach(b=>b.onclick=()=>navigate('inbox',b.dataset.label));}
function navigate(next,label=''){folder=next;labelFilter=label;unreadOnly=false;back();$('.sidebar').classList.remove('mobile-open');render();}
function back(){opened=null;$('#inbox-view').hidden=false;$('#reader-view').hidden=true;render();}
function openMessage(id){const m=state.messages.find(m=>m.id===id);if(!m)return;selected=id;opened=id;m.unread=false;save();render();$('#inbox-view').hidden=true;$('#reader-view').hidden=false;renderReader(m);}
function renderReader(m){$('#reader-view').innerHTML=`<div class="reader-toolbar"><button class="back-button" id="back-to-inbox">${icon('arrowLeft')}Back <kbd>esc</kbd></button><div class="reader-actions"><button class="icon-button" id="reader-done" title="Mark done (E)" aria-label="Mark conversation done">${icon('checkCircle')}</button><button class="icon-button" id="reader-snooze" title="Snooze (H)" aria-label="Snooze conversation">${icon('clock')}</button><button class="icon-button ${m.starred?'unread-filter-on':''}" id="reader-star" title="Star (S)" aria-label="Star conversation">${icon('star')}</button><button class="icon-button" id="reader-unread" title="Mark unread" aria-label="Mark unread">${icon('mail')}</button></div></div><h1>${esc(m.subject)}</h1><div class="reader-sender"><div class="sender-avatar" style="background:${m.color};color:${m.ink}">${esc(m.initials)}</div><div><strong>${esc(m.name)}</strong><small>${esc(m.email)} · to ${m.folder==='sent'?esc(m.to):'me'}</small></div><span>${esc(m.time)}</span></div><div class="reader-body">${m.body.split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('')}${m.attachment?`<div class="mail-attachment">${icon('paperclip')}<span>${esc(m.attachment)}<small style="display:block;font-size:9px;color:#b3a3bf;margin-top:4px">Sample attachment · preview unavailable</small></span></div>`:''}</div><div class="reader-reply" id="reader-reply"><span>Reply to ${esc(m.name.split(' ')[0])}…</span><button aria-label="Reply to sender">${icon('reply')}</button></div>`;$('#back-to-inbox').onclick=back;$('#reader-done').onclick=()=>markDone(m.id);$('#reader-snooze').onclick=()=>showSnooze();$('#reader-star').onclick=()=>toggleStar(m.id);$('#reader-unread').onclick=()=>{saveUndo();m.unread=true;save();back();toast('Marked as unread.',true);};$('#reader-reply').onclick=()=>reply();}
function targetMessage(){return state.messages.find(m=>m.id===(opened||selected));}
function markDone(id){const m=state.messages.find(m=>m.id===(id||opened||selected));if(!m)return toast('Select a conversation first.');saveUndo();m.folder=m.folder==='done'?'inbox':'done';delete m.snoozeUntil;save();if(opened)back();else render();toast(m.folder==='done'?'Conversation marked done. A little more breathing room.':'Conversation moved to inbox.',true);}
function toggleStar(id){const m=state.messages.find(m=>m.id===(id||opened||selected));if(!m)return;saveUndo();m.starred=!m.starred;save();render();if(opened)renderReader(m);toast(m.starred?'Starred for later.':'Star removed.',true);}
function showSnooze(){if(!targetMessage())return toast('Select a conversation first.');$('#snooze-dialog').showModal();const min=new Date(Date.now()+60000);$('#custom-snooze').min=localDateTime(min);}
function localDateTime(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function snooze(until){const m=targetMessage();if(!m)return;if(!Number.isFinite(until)||until<=Date.now())return toast('Choose a future date and time.');saveUndo();m.folder='snoozed';m.snoozeUntil=until;save();$('#snooze-dialog').close();back();toast(`Snoozed until ${new Date(until).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.`,true);}
function showCompose(draft=null){editingDraftId=draft?.id||null;$('#compose-to').value=draft?.to||'';$('#compose-subject').value=draft?.subject||'';$('#compose-body').value=draft?.body||'';$('#compose-title').textContent=draft?.reply?'Reply':'New message';$('#compose-dialog').showModal();$('#compose-to').focus();}
function persistDraft(){const to=$('#compose-to').value,subject=$('#compose-subject').value,body=$('#compose-body').value;if(!to&&!subject&&!body){if(editingDraftId){state.drafts=state.drafts.filter(d=>d.id!==editingDraftId);editingDraftId=null;save();render();}return;}const d={id:editingDraftId||Date.now(),to,subject,body};editingDraftId=d.id;const index=state.drafts.findIndex(x=>x.id===d.id);if(index===-1)state.drafts.push(d);else state.drafts[index]=d;save();$('#drafts-count').textContent=state.drafts.length;}
function openDraft(id){showCompose(state.drafts.find(d=>d.id===id));}
function reply(){const m=targetMessage();if(!m)return toast('Open a conversation to reply.');showCompose({to:m.folder==='sent'?m.to:m.email,subject:m.subject.startsWith('Re:')?m.subject:'Re: '+m.subject,reply:true});$('#compose-body').focus();}
function closeDialog(id){$('#'+id).close();}
function showPalette(mode='commands'){paletteMode=mode;paletteIndex=0;$('#palette-input').value='';$('#palette-input').placeholder=mode==='search'?'Search conversations, people, subjects…':'What would you like to do?';$('#palette-label').textContent=mode==='search'?'ALL CONVERSATIONS':'SUGGESTED ACTIONS';renderPalette();$('#palette-dialog').showModal();$('#palette-input').focus();}
const commands=[{name:'Compose a message',icon:'plus',key:'C',run:()=>showCompose()},{name:'Mark conversation done',icon:'checkCircle',key:'E',run:()=>markDone()},{name:'Snooze conversation',icon:'clock',key:'H',run:()=>showSnooze()},{name:'Star / unstar conversation',icon:'star',key:'S',run:()=>toggleStar()},{name:'Search all conversations',icon:'search',key:'/',run:()=>showPalette('search')},{name:'Go to Inbox',icon:'inbox',run:()=>navigate('inbox')},{name:'Go to Starred',icon:'star',run:()=>navigate('starred')},{name:'Go to Snoozed',icon:'clock',run:()=>navigate('snoozed')},{name:'Go to Drafts',icon:'file',run:()=>navigate('drafts')},{name:'Go to Sent',icon:'send',run:()=>navigate('sent')},{name:'Go to Done',icon:'archive',run:()=>navigate('done')},{name:'Mark all in this view as read',icon:'mail',run:()=>markAllRead()},{name:'Move conversation to Other / Important',icon:'filter',run:()=>moveSplit()},{name:'Label conversation',icon:'file',run:()=>labelConversation()},{name:'Keyboard shortcuts',icon:'keyboard',key:'?',run:()=>$('#shortcuts-dialog').showModal()},{name:'Toggle focus mode',icon:'maximize',run:()=>toggleFocus()},{name:'Undo last action',icon:'arrowLeft',key:'Z',run:()=>undo()}];
function renderPalette(){const q=$('#palette-input').value.toLowerCase().trim();if(paletteMode==='search'){paletteItems=state.messages.filter(m=>`${m.name} ${m.email} ${m.subject} ${m.body} ${m.label}`.toLowerCase().includes(q));}else if(paletteMode==='labels')paletteItems=state.labels.filter(name=>name.toLowerCase().includes(q)).map(name=>({name,icon:'file',run:()=>{const m=state.messages.find(m=>m.id===labelTarget);if(!m)return;saveUndo();m.label=name;save();render();toast(`Labeled ${name}.`,true);}}));else paletteItems=commands.filter(c=>c.name.toLowerCase().includes(q));paletteIndex=Math.min(paletteIndex,Math.max(0,paletteItems.length-1));$('#palette-results').innerHTML=paletteItems.length?paletteItems.map((item,i)=>paletteMode==='search'?`<button class="search-result ${i===paletteIndex?'active':''}" data-palette-index="${i}"><span class="sender-avatar" style="background:${item.color};color:${item.ink}">${esc(item.initials)}</span><div><strong>${esc(item.subject)}</strong><small>${esc(item.name)} · ${esc(item.folder)}</small></div></button>`:`<button class="palette-command ${i===paletteIndex?'active':''}" data-palette-index="${i}">${icon(item.icon)}<span>${esc(item.name)}</span>${item.key?`<kbd>${item.key}</kbd>`:''}</button>`).join(''):'<div class="no-results">No matches. Try a different word.</div>';$('#palette-results').style.maxHeight='390px';$('#palette-results').style.overflowY='auto';$$('[data-palette-index]').forEach(b=>b.onclick=()=>activatePalette(Number(b.dataset.paletteIndex)));}
function activatePalette(index){const item=paletteItems[index];if(!item)return;$('#palette-dialog').close();if(paletteMode==='search'){folder=item.folder;labelFilter='';split=item.split;unreadOnly=false;openMessage(item.id);}else item.run();}
function markAllRead(){const list=visibleMessages();if(!list.length)return;saveUndo();list.forEach(m=>{const original=state.messages.find(x=>x.id===m.id);if(original)original.unread=false;});save();render();toast('All conversations in this view marked read.',true);}
function moveSplit(){const m=targetMessage();if(!m)return toast('Select a conversation first.');saveUndo();m.split=m.split==='important'?'other':'important';save();back();toast(`Moved to ${m.split==='important'?'Important':'Other'}.`,true);}
function labelConversation(){const m=targetMessage();if(!m)return toast('Select a conversation first.');labelTarget=m.id;showPalette('labels');$('#palette-input').placeholder='Find a label…';$('#palette-label').textContent='APPLY LABEL';}
function toggleFocus(){document.body.classList.toggle('focus-layout');}
function renderCalendar(){const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth();$('#calendar-month').textContent=calendarMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'});const firstDay=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),cells=Math.ceil((firstDay+days)/7)*7;$('#calendar-grid').innerHTML=Array.from({length:cells},(_,i)=>{const date=new Date(year,month,i-firstDay+1),isToday=date.toDateString()===now.toDateString(),chosen=date.toDateString()===calendarDay.toDateString();return `<button class="${date.getMonth()!==month?'outside':''} ${isToday?'today':''} ${chosen?'chosen':''} ${[2,6,9,16,21,23,27].includes(date.getDate())?'has-events':''}" data-date="${date.getTime()}" aria-label="${date.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}" ${isToday?'aria-current="date"':''}>${date.getDate()}</button>`;}).join('');$$('[data-date]').forEach(b=>b.onclick=()=>{calendarDay=new Date(Number(b.dataset.date));renderCalendar();$('#schedule-date').textContent=calendarDay.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});const today=calendarDay.toDateString()===now.toDateString();$$('.event').forEach(e=>e.hidden=!today);$('.schedule-heading>span').textContent=today?'3 events':'No events';$('.agenda-sample').innerHTML=icon('info')+(today?'Sample schedule':'Nothing scheduled. A little breathing room.');});$('#schedule-date').textContent=calendarDay.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});}
function handleAction(action){({compose:()=>showCompose(),search:()=>showPalette('search'),commands:()=>showPalette(),shortcuts:()=>$('#shortcuts-dialog').showModal()})[action]?.();}
$$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));$$('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));$$('[data-folder]').forEach(b=>b.onclick=()=>navigate(b.dataset.folder));$$('[data-split]').forEach(b=>b.onclick=()=>{split=b.dataset.split;opened=null;unreadOnly=false;render();});$('.brand').onclick=e=>{e.preventDefault();navigate('inbox');};
$('#compose-form').onsubmit=e=>{e.preventDefault();saveUndo();const message={id:Date.now(),name:'Alex Johnson',email:'alex@studio.co',to:$('#compose-to').value,initials:'AJ',color:'#e9e3f4',ink:'#9c8ab0',subject:$('#compose-subject').value,body:$('#compose-body').value,preview:$('#compose-body').value.replaceAll('\n',' '),time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),folder:'sent',split:'important',unread:false,starred:false};state.messages.unshift(message);state.drafts=state.drafts.filter(d=>d.id!==editingDraftId);editingDraftId=null;$('#compose-form').reset();save();$('#compose-dialog').close();render();toast('Message saved to Sent. Demo only — no email was sent.',true);};
$('#compose-form').addEventListener('input',persistDraft);$('#compose-dialog').addEventListener('close',()=>{persistDraft();render();});$('#discard-draft').onclick=()=>{saveUndo();state.drafts=state.drafts.filter(d=>d.id!==editingDraftId);editingDraftId=null;$('#compose-form').reset();save();$('#compose-dialog').close();render();toast('Draft discarded.',true);};
$('#palette-input').oninput=()=>{paletteIndex=0;renderPalette();};$('#palette-input').onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();paletteIndex=Math.max(0,Math.min(paletteItems.length-1,paletteIndex+(e.key==='ArrowDown'?1:-1)));$$('[data-palette-index]').forEach((b,i)=>b.classList.toggle('active',i===paletteIndex));$(`[data-palette-index="${paletteIndex}"]`)?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();activatePalette(paletteIndex);}};
$$('[data-snooze]').forEach(b=>b.onclick=()=>{const d=new Date();if(b.dataset.snooze==='later')d.setHours(d.getHours()+3);else{d.setHours(9,0,0,0);d.setDate(d.getDate()+(b.dataset.snooze==='tomorrow'?1:((8-d.getDay())%7||7)));}snooze(d.getTime());});$('#confirm-custom-snooze').onclick=()=>snooze(new Date($('#custom-snooze').value).getTime());
$('#filter-unread').onclick=()=>{unreadOnly=!unreadOnly;render();};$('#focus-mode').onclick=toggleFocus;$('#list-menu').onclick=()=>showPalette();$('#toggle-agenda').onclick=()=>{const agenda=$('#agenda');if(window.innerWidth<=1050)agenda.classList.toggle('revealed');else agenda.hidden=!agenda.hidden;};$('#mobile-menu').onclick=e=>{e.stopPropagation();$('.sidebar').classList.toggle('mobile-open');};document.addEventListener('click',e=>{if(!e.target.closest('.sidebar')&&!e.target.closest('#mobile-menu'))$('.sidebar').classList.remove('mobile-open');});$('#account').onclick=()=>toast('Alex’s sample workspace. No email account is connected.');$('#previous-month').onclick=()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);renderCalendar();};$('#next-month').onclick=()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);renderCalendar();};$('#add-label').onclick=()=>{$('#label-form').reset();$('#label-dialog').showModal();};$('#label-form').onsubmit=e=>{e.preventDefault();const name=$('#label-name').value.trim();if(!name)return;if(state.labels.some(l=>l.toLowerCase()===name.toLowerCase()))return toast('That label already exists.');saveUndo();state.labels.push(name);save();render();$('#label-dialog').close();toast(`Label “${name}” created. Use Commands to label a conversation.`,true);};
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.addEventListener('keydown',e=>{const dialog=$('dialog[open]');if(dialog){if(dialog.id==='compose-dialog'&&(e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();$('#compose-form').requestSubmit();}return;}if(e.target.matches('input,textarea,[contenteditable]'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showPalette();return;}if(e.metaKey||e.ctrlKey||e.altKey)return;
if(['j','k','ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const list=visibleMessages(),index=list.findIndex(m=>m.id===selected),next=list[Math.max(0,Math.min(list.length-1,index+(['j','ArrowDown'].includes(e.key)?1:-1)))];if(next){selected=next.id;if(opened)openMessage(next.id);else{render();$(`[data-id="${selected}"]`)?.scrollIntoView({block:'nearest'});}}return;}
if(e.key==='Enter'&&e.target.closest('button,a'))return;if(e.key==='Enter'&&selected){e.preventDefault();if(folder==='drafts')openDraft(selected);else openMessage(selected);}else if(e.key==='Escape'&&opened)back();else if(e.key==='/'){e.preventDefault();showPalette('search');}else if(e.key==='?'){e.preventDefault();$('#shortcuts-dialog').showModal();}else if(e.key.toLowerCase()==='c'){e.preventDefault();showCompose();}else if(e.key.toLowerCase()==='e'){e.preventDefault();markDone();}else if(e.key.toLowerCase()==='s')toggleStar();else if(e.key.toLowerCase()==='h')showSnooze();else if(e.key.toLowerCase()==='r')reply();else if(e.key.toLowerCase()==='z')undo();});
hydrateIcons();wakeSnoozed();render();renderCalendar();save();setInterval(wakeSnoozed,30000);
